(6605102, 985778, 124190, '<td valign="top">UG   HATE those things!   suckers!!! literally....makes me itch....there''s always some insect ruining something!   lolol</td>', 'UG   HATE those things!   suckers!!! literally....makes me itch....there''s always some insect ruining something!   lolol', '2011-11-28 09:22:38.000000', NULL, 1),
(6605103, 985823, 10785, '<td valign="top">Where did you find one single cattail standing alone?? Setup?? hehe. Well I like the selective desat, but I would like to see a full color version to compare. I think the eye goes into the distance on this photo bypassing the main subject. The leading lines of the hills in the background pulls me right in. You captured nice light in the sky and lit the subject well too.</td>', 'Where did you find one single cattail standing alone?? Setup?? hehe. Well I like the selective desat, but I would like to see a full color version to compare. I think the eye goes into the distance on this photo bypassing the main subject. The leading lines of the hills in the background pulls me right in. You captured nice light in the sky and lit the subject well too.', '2011-11-28 09:22:59.000000', NULL, 1),
(6605107, 985789, 10785, '<td valign="top">All the technicals are good... focus, sharpness, exposure, color. I think the composition is a bit lacking. You have filled the frame with similar subjects and haven''t used any method to create a focal point such as use of depth of field, rule of thirds, etc. I think the centered leaf is somewhat of a focal point but it needs to stand out more.</td>', 'All the technicals are good... focus, sharpness, exposure, color. I think the composition is a bit lacking. You have filled the frame with similar subjects and haven''t used any method to create a focal point such as use of depth of field, rule of thirds, etc. I think the centered leaf is somewhat of a focal point but it needs to stand out more.', '2011-11-28 09:26:46.000000', NULL, 1),
(6605109, 985781, 10785, '<td valign="top">Nice light on the main subject. Could stand a little more detail on the bee.</td>', 'Nice light on the main subject. Could stand a little more detail on the bee.', '2011-11-28 09:27:51.000000', NULL, 1),
(6605125, 985319, 93421, '<td valign="top">My pick for the Blue.  Great POV and DOF.  Good luck!</td>', 'My pick for the Blue.  Great POV and DOF.  Good luck!', '2011-11-28 09:46:55.000000', NULL, 1),
(6605195, 985673, 111483, '<td valign="top">very sharp and very nice picture i love it great job</td>', 'very sharp and very nice picture i love it great job', '2011-11-28 11:07:37.000000', NULL, 1),
(6605341, 985642, 124982, '<td valign="top">Quite beautiful...love the detail in this! Strikes me as HDR almost?</td>', 'Quite beautiful...love the detail in this! Strikes me as HDR almost?', '2011-11-28 18:46:07.000000', NULL, 1),
(6605357, 985803, 109363, '<td valign="top">i love gum tree leaves!</td>', 'i love gum tree leaves!', '2011-11-28 19:10:52.000000', NULL, 1),
(6605359, 985577, 109363, '<td valign="top">not sure what to make of this... in itself, not a remarkable composition, but at least on my monitor this looks almost 3-D.  interesting.</td>', 'not sure what to make of this... in itself, not a remarkable composition, but at least on my monitor this looks almost 3-D.  interesting.', '2011-11-28 19:14:02.000000', NULL, 1),
(6605360, 985577, 114285, '<td valign="top">Pretty amazing shot, one of the better ones.</td>', 'Pretty amazing shot, one of the better ones.', '2011-11-28 19:14:29.000000', NULL, 1),
(6605403, 985783, 17507, '<td valign="top">Sharpness, focus, and lighting all very well handled in this most classic of botanical subjects--the bug definitely adds a unique twist, but not sure how I feel about its placement, since it makes the composition feel very bottom-heavy and the right quarter or so of the image seem like dead space.</td>', 'Sharpness, focus, and lighting all very well handled in this most classic of botanical subjects--the bug definitely adds a unique twist, but not sure how I feel about its placement, since it makes the composition feel very bottom-heavy and the right quarter or so of the image seem like dead space.', '2011-11-28 20:16:44.000000', NULL, 1),
(6605405, 985607, 10785, '<td valign="top">The biosphere gives it that scientific edge... the golden light on the trees helps to enhance the great texture in the scene.</td>', 'The biosphere gives it that scientific edge... the golden light on the trees helps to enhance the great texture in the scene.', '2011-11-28 20:16:51.000000', NULL, 1),
(6605408, 985709, 17507, '<td valign="top">"Not bad" was my initial thought--for this to really pop, you need at least to have a sharp focus on the center of the flower, perhaps a narrower DOF to make the edges fade into blur--also I find myself wondering if a square crop would have better suited the subject/basic composition.</td>', '"Not bad" was my initial thought--for this to really pop, you need at least to have a sharp focus on the center of the flower, perhaps a narrower DOF to make the edges fade into blur--also I find myself wondering if a square crop would have better suited the subject/basic composition.', '2011-11-28 20:17:56.000000', NULL, 1),
(6605409, 985774, 10785, '<td valign="top">I think a different angle could have been used to isolate the one subject and eliminate the background grass on the left side. Otherwise, nice light and good bokeh background.</td>', 'I think a different angle could have been used to isolate the one subject and eliminate the background grass on the left side. Otherwise, nice light and good bokeh background.', '2011-11-28 20:18:19.000000', NULL, 1),
(6605411, 985189, 17507, '<td valign="top">Brilliant lighting, love the high contrast. The yellows really work. Focus seems a bit off--your focal plane is not even with the flower, so parts that seem like they should be sharp wind up being soft. Not much going on in the far right--I think you could have cropped tighter without losing anything important.</td>', 'Brilliant lighting, love the high contrast. The yellows really work. Focus seems a bit off--your focal plane is not even with the flower, so parts that seem like they should be sharp wind up being soft. Not much going on in the far right--I think you could have cropped tighter without losing anything important.', '2011-11-28 20:19:03.000000', NULL, 1),
(6605413, 985581, 10785, '<td valign="top">Nice composition. I think the angled line created by the greenish leaves serve to allow the yellowish leaf to stand out isolated more as a focal point.</td>', 'Nice composition. I think the angled line created by the greenish leaves serve to allow the yellowish leaf to stand out isolated more as a focal point.', '2011-11-28 20:20:06.000000', NULL, 1),
(6605415, 985686, 17507, '<td valign="top">Love the tones, the complexity of the image combined with the relative simplicity of the composition, and a unique take on a very-thoroughly-photographed subject. Blur on the left seems a bit odd though--like a partially-transparent gaussian blur layer rather than "proper" blur from a shallow DOF--distracts a bit from an otherwise very cool photo.</td>', 'Love the tones, the complexity of the image combined with the relative simplicity of the composition, and a unique take on a very-thoroughly-photographed subject. Blur on the left seems a bit odd though--like a partially-transparent gaussian blur layer rather than "proper" blur from a shallow DOF--distracts a bit from an otherwise very cool photo.', '2011-11-28 20:21:16.000000', NULL, 1),
(6605416, 985240, 17507, '<td valign="top">I like the choice of subject and the rhythm the leaves create--but since that''s the primary interest in this photo, I think you could have zoomed/cropped quite a bit tighter on the zigzag and gotten a much stronger impact that way.</td>', 'I like the choice of subject and the rhythm the leaves create--but since that''s the primary interest in this photo, I think you could have zoomed/cropped quite a bit tighter on the zigzag and gotten a much stronger impact that way.', '2011-11-28 20:22:22.000000', NULL, 1),
(6605417, 985778, 17507, '<td valign="top">No objections to the subject matter, although it is a bit icky--definitely untraditional, which appeals to me--soft focus, flat lighting, and what strikes me as poorly planned composition detract from this photo''s effectiveness, unfortunately.</td>', 'No objections to the subject matter, although it is a bit icky--definitely untraditional, which appeals to me--soft focus, flat lighting, and what strikes me as poorly planned composition detract from this photo''s effectiveness, unfortunately.', '2011-11-28 20:23:25.000000', NULL, 1),
(6605420, 985105, 17507, '<td valign="top">Nice take on a classic subject! Lighting, sharpness, DOF all very well controlled and demonstrate a high degree of skill. The magnifying glass and hand do a lot to tie the photo directly to the challenge (which also sets this photo apart, since it seems many people--including me--interpreted the challenge as "take a picture of a plant").</td>', 'Nice take on a classic subject! Lighting, sharpness, DOF all very well controlled and demonstrate a high degree of skill. The magnifying glass and hand do a lot to tie the photo directly to the challenge (which also sets this photo apart, since it seems many people--including me--interpreted the challenge as "take a picture of a plant").', '2011-11-28 20:24:57.000000', NULL, 1),
(6605424, 985834, 17507, '<td valign="top">I like the bleakness, the composition, the B/W and shallow DOF; I wonder if some vignetting (strong or subtle, either way) could have added some pop.</td>', 'I like the bleakness, the composition, the B/W and shallow DOF; I wonder if some vignetting (strong or subtle, either way) could have added some pop.', '2011-11-28 20:25:46.000000', NULL, 1),
(6605434, 985823, 17507, '<td valign="top">Quite reminiscent of <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=30861" rel="nofollow" target="_blank">Bear_Music</a> to me, which is never a bad thing, whether you''re Robert or not--although selective desat is not something he tends to do, so I''m guessing this is not him. I guess it works here because it makes a strong focal point out of what otherwise would be a weak foreground element, although I generally disfavor the technique except in rare circumstances. Still, nicely delivered, with good deep DOF and solid representation of a full range of blacks and whites.</td>', 'Quite reminiscent of  Bear_Music to me, which is never a bad thing, whether you''re Robert or not--although selective desat is not something he tends to do, so I''m guessing this is not him. I guess it works here because it makes a strong focal point out of what otherwise would be a weak foreground element, although I generally disfavor the technique except in rare circumstances. Still, nicely delivered, with good deep DOF and solid representation of a full range of blacks and whites.', '2011-11-28 20:29:02.000000', NULL, 1),
(6605436, 984981, 17507, '<td valign="top">Weird-ass grainy high-contrast abstract macro of alien-looking plants... I dig. I think my vote is going to raise your average score</td>', 'Weird-ass grainy high-contrast abstract macro of alien-looking plants... I dig. I think my vote is going to raise your average score', '2011-11-28 20:29:36.000000', NULL, 1),
(6605439, 985710, 17507, '<td valign="top">Focus well controlled, shallow DOF and even lighting seem appropriate to your subject--but there''s nothing here to grab my attention and keep me engaged. I''d give this a 5.5 if I could because it just screams "average" to me, but I''m rounding up to a 6</td>', 'Focus well controlled, shallow DOF and even lighting seem appropriate to your subject--but there''s nothing here to grab my attention and keep me engaged. I''d give this a 5.5 if I could because it just screams "average" to me, but I''m rounding up to a 6', '2011-11-28 20:30:49.000000', NULL, 1),
(6605442, 985786, 17507, '<td valign="top">Nice high-contrast/mostly-high-key minimalism--I dig the composition, but wish the bottom seed were as sharp as the other two</td>', 'Nice high-contrast/mostly-high-key minimalism--I dig the composition, but wish the bottom seed were as sharp as the other two', '2011-11-28 20:31:25.000000', NULL, 1),
(6605452, 985472, 17507, '<td valign="top">Your reptile friend is the focus of this image, which sort of makes it DNMC, since the challenge description says: "Capture a well-composed image that has plant life as its central theme." Regardless, photographically, I think this would have been a much stronger image with a far tighter crop on the iguana--would have made the nice shallow DOF even more effective.</td>', 'Your reptile friend is the focus of this image, which sort of makes it DNMC, since the challenge description says: "Capture a well-composed image that has plant life as its central theme." Regardless, photographically, I think this would have been a much stronger image with a far tighter crop on the iguana--would have made the nice shallow DOF even more effective.', '2011-11-28 20:36:56.000000', NULL, 1),
(6605454, 985796, 17507, '<td valign="top">Dig the punny title. Choice of subject seems good, but the angle had led to a static composition, and the lighting is flat. Maybe back up some? Try a night shot? Come in closer with a wide-angle lens? I see a lot of potential in this building, but the end result seems unfortunately quite sterile.</td>', 'Dig the punny title. Choice of subject seems good, but the angle had led to a static composition, and the lighting is flat. Maybe back up some? Try a night shot? Come in closer with a wide-angle lens? I see a lot of potential in this building, but the end result seems unfortunately quite sterile.', '2011-11-28 20:38:20.000000', NULL, 1),
(6605458, 985592, 17507, '<td valign="top">Good DOF &amp; overall control of focus and lighting. Composition feels a bit "stretched" -- wonder if you could have boosted the impact by cutting a bit off of the left and right. Nonetheless, a pleasing photo, and one of the better ones I''ve seen so far</td>', 'Good DOF & overall control of focus and lighting. Composition feels a bit "stretched" -- wonder if you could have boosted the impact by cutting a bit off of the left and right. Nonetheless, a pleasing photo, and one of the better ones I''ve seen so far', '2011-11-28 20:39:23.000000', NULL, 1),
(6605462, 985678, 17507, '<td valign="top">Very nice. I''d have to think really hard to come up with constructive criticism for this photo... it''s just very nicely handled in all respects, from concept to execution.</td>', 'Very nice. I''d have to think really hard to come up with constructive criticism for this photo... it''s just very nicely handled in all respects, from concept to execution.', '2011-11-28 20:40:35.000000', NULL, 1),
(6605470, 985772, 17507, '<td valign="top">If you''re going to shoot a rose, you really have to make sure it''s a fantastic shot, otherwise it just winds up looking like all the other pictures of roses out there... that being said, it looks like you spent a while with this and were working outside of your comfort zone, which I always think is great and will make you a better photographer... unfortunately I cannot in good faith give this a high score, but I hope you will keep pushing yourself and entering.</td>', 'If you''re going to shoot a rose, you really have to make sure it''s a fantastic shot, otherwise it just winds up looking like all the other pictures of roses out there... that being said, it looks like you spent a while with this and were working outside of your comfort zone, which I always think is great and will make you a better photographer... unfortunately I cannot in good faith give this a high score, but I hope you will keep pushing yourself and entering.', '2011-11-28 20:42:41.000000', NULL, 1),
(6605475, 985032, 17507, '<td valign="top">Great sense of scale: there''s a grandness to this photo that''s hard to plan or learn how to create deliberately. But definitely the soft light and the glowy/faded-gaussian-blur treatment lend to that. Nicely done.</td>', 'Great sense of scale: there''s a grandness to this photo that''s hard to plan or learn how to create deliberately. But definitely the soft light and the glowy/faded-gaussian-blur treatment lend to that. Nicely done.', '2011-11-28 20:43:44.000000', NULL, 1),
(6605500, 985608, 3306, '<td valign="top">Well done.</td>', 'Well done.', '2011-11-28 20:55:15.000000', NULL, 1),
(6605573, 985430, 128201, '<td valign="top">Wow, you were lucky to get one that flowered the week of the challenge! This plant isn''t much to look at, but the amazing flower makes up for it in a single night.</td>', 'Wow, you were lucky to get one that flowered the week of the challenge! This plant isn''t much to look at, but the amazing flower makes up for it in a single night.', '2011-11-28 23:35:50.000000', NULL, 1),
(6605605, 985686, 114285, '<td valign="top">Gorgeous one of the best.</td>', 'Gorgeous one of the best.', '2011-11-29 01:31:13.000000', NULL, 1),
(6605606, 985718, 114285, '<td valign="top">Technically flawless, it just lacks soul and doesn''t really do anything for me, but that''s just me, I prefer nature to take course where it grows. Still in saying that I''m sure the DPer''s will love it.</td>', 'Technically flawless, it just lacks soul and doesn''t really do anything for me, but that''s just me, I prefer nature to take course where it grows. Still in saying that I''m sure the DPer''s will love it.', '2011-11-29 01:34:51.000000', NULL, 1),
(6605607, 985827, 114285, '<td valign="top">THis is just too busy to be interesting, all though it does has some nice foilage in the shot.</td>', 'THis is just too busy to be interesting, all though it does has some nice foilage in the shot.', '2011-11-29 01:35:38.000000', NULL, 1),
(6605608, 985767, 114285, '<td valign="top">Technically great shot and the  Dper''s seem to love this sterile smooth and precise shot, not for me though, but no doubt I''m sure it will do well.</td>', 'Technically great shot and the  Dper''s seem to love this sterile smooth and precise shot, not for me though, but no doubt I''m sure it will do well.', '2011-11-29 01:37:30.000000', NULL, 1),
(6605609, 985319, 114285, '<td valign="top">Awesome, awesome and did I say AWESOME shot. The way you''ve focused on the leaves is what grabs me. 9</td>', 'Awesome, awesome and did I say AWESOME shot. The way you''ve focused on the leaves is what grabs me. 9', '2011-11-29 01:38:51.000000', NULL, 1),
(6605612, 985735, 114285, '<td valign="top">Pretty shot, i entered one of these but pulled it out in favour for another shot, the stripy bokeh is awesome.</td>', 'Pretty shot, i entered one of these but pulled it out in favour for another shot, the stripy bokeh is awesome.', '2011-11-29 01:41:08.000000', NULL, 1),
(6605709, 985642, 114225, '<td valign="top">Nice study of lines and textures. Almost feels like an x-ray.</td>', 'Nice study of lines and textures. Almost feels like an x-ray.', '2011-11-29 10:23:54.000000', NULL, 1),
(6605710, 985774, 114225, '<td valign="top">I can just imagine this grass flowing in the wind, making a light hushing sound.</td>', 'I can just imagine this grass flowing in the wind, making a light hushing sound.', '2011-11-29 10:24:28.000000', NULL, 1),
(6605711, 985737, 114225, '<td valign="top">Great view on autumn''s change.</td>', 'Great view on autumn''s change.', '2011-11-29 10:24:39.000000', NULL, 1),
(6605712, 985353, 114225, '<td valign="top">Cool idea, and nicely executed. The blue background helps the green to really pop.</td>', 'Cool idea, and nicely executed. The blue background helps the green to really pop.', '2011-11-29 10:25:19.000000', NULL, 1),
(6605713, 985812, 114225, '<td valign="top">Nicely photographed. You captured a lot of mood in this photo.</td>', 'Nicely photographed. You captured a lot of mood in this photo.', '2011-11-29 10:25:37.000000', NULL, 1),
(6605716, 985805, 114225, '<td valign="top">I really enjoy how you lit this. The lanterns almost appear to be providing the light.</td>', 'I really enjoy how you lit this. The lanterns almost appear to be providing the light.', '2011-11-29 10:26:16.000000', NULL, 1),
(6605717, 985598, 114225, '<td valign="top">I enjoy the textures of this photograph quite a bit.</td>', 'I enjoy the textures of this photograph quite a bit.', '2011-11-29 10:26:37.000000', NULL, 1),
(6605718, 985457, 114225, '<td valign="top">What a cool flower. So much going on in such a small space.</td>', 'What a cool flower. So much going on in such a small space.', '2011-11-29 10:27:00.000000', NULL, 1),
(6605719, 985671, 114225, '<td valign="top">Very nice use of complimentary colors to highlight your subject.</td>', 'Very nice use of complimentary colors to highlight your subject.', '2011-11-29 10:27:19.000000', NULL, 1),
(6605720, 985610, 114225, '<td valign="top">I very much enjoy this photo. It''s simple, yet effective.</td>', 'I very much enjoy this photo. It''s simple, yet effective.', '2011-11-29 10:27:43.000000', NULL, 1),
(6605721, 985576, 114225, '<td valign="top">So much mood and story in a simple photograph of a dead leaf. Nicely done.</td>', 'So much mood and story in a simple photograph of a dead leaf. Nicely done.', '2011-11-29 10:28:28.000000', NULL, 1),
(6605722, 985429, 114225, '<td valign="top">Such nice use of light and shadows to show texture.</td>', 'Such nice use of light and shadows to show texture.', '2011-11-29 10:29:10.000000', NULL, 1),
(6605741, 985472, 114225, '<td valign="top">This is very cool. Great use of color and depth of field.</td>', 'This is very cool. Great use of color and depth of field.', '2011-11-29 11:34:21.000000', NULL, 1),
(6605742, 985650, 114225, '<td valign="top">Kind of a mystical feel to this photo which is pretty cool.</td>', 'Kind of a mystical feel to this photo which is pretty cool.', '2011-11-29 11:34:55.000000', NULL, 1),
(6605744, 985672, 114225, '<td valign="top">Great detail of this flesh eating plant.</td>', 'Great detail of this flesh eating plant.', '2011-11-29 11:35:26.000000', NULL, 1),
(6605751, 985608, 16046, '<td valign="top">I love bitter melon, interesting</td>', 'I love bitter melon, interesting', '2011-11-29 11:48:23.000000', NULL, 1),
(6605753, 985651, 16046, '<td valign="top">Best in show, awesome!</td>', 'Best in show, awesome!', '2011-11-29 12:00:05.000000', NULL, 1),
(6605755, 985752, 16046, '<td valign="top">You must have gotten a bit dirty taking this, well done!</td>', 'You must have gotten a bit dirty taking this, well done!', '2011-11-29 12:02:09.000000', NULL, 1),
(6605763, 985739, 73942, '<td valign="top">what a wonderful find and lovely capture</td>', 'what a wonderful find and lovely capture', '2011-11-29 12:29:54.000000', NULL, 1),
(6605836, 985767, 114225, '<td valign="top">It''s interesting, my mind wants to switch the order a bit to have #2 and #3 in different positions to create more of an "order."</td>', 'It''s interesting, my mind wants to switch the order a bit to have #2 and #3 in different positions to create more of an "order."', '2011-11-29 14:25:59.000000', NULL, 1),
(6605850, 985767, 17507, '<td valign="top">Glass, mirrors, and water... classic ingredients for a successful DPC shot. And I do like it--it''s pleasing visually, it ties well to the challenge theme, and the concept is clever and original. Despite my feeling that you''d have a stronger image with better control of reflections (use a polarizer, maybe?), I still find this quite successfully executed and am scoring it highly.</td>', 'Glass, mirrors, and water... classic ingredients for a successful DPC shot. And I do like it--it''s pleasing visually, it ties well to the challenge theme, and the concept is clever and original. Despite my feeling that you''d have a stronger image with better control of reflections (use a polarizer, maybe?), I still find this quite successfully executed and am scoring it highly.', '2011-11-29 14:46:14.000000', NULL, 1),
(6605851, 985213, 17507, '<td valign="top">Great colors, love the high contrast and crisp detail. (I think you could have used a somewhat narrower aperture to good effect so that you could get more of the crunchy dried-out-ness good and razor-sharp.) The lower right is all dead area, though--if you''d burned that down to tones closer to the upper left, I think you''d have a much better balanced image that creates a stronger focus on the center of the rose.</td>', 'Great colors, love the high contrast and crisp detail. (I think you could have used a somewhat narrower aperture to good effect so that you could get more of the crunchy dried-out-ness good and razor-sharp.) The lower right is all dead area, though--if you''d burned that down to tones closer to the upper left, I think you''d have a much better balanced image that creates a stronger focus on the center of the rose.', '2011-11-29 14:48:28.000000', NULL, 1),
(6605853, 985700, 17507, '<td valign="top">Great lighting and colors. Maybe a slightly tighter crop, take a bit off of the left and right? I think some local sharpening at the center of the rose would have also added an extra pop. Well done in any event.</td>', 'Great lighting and colors. Maybe a slightly tighter crop, take a bit off of the left and right? I think some local sharpening at the center of the rose would have also added an extra pop. Well done in any event.', '2011-11-29 14:49:40.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6605855, 985757, 17507, '<td valign="top">I like the choice of subject matter; many complex shapes, very organic, strong sense of movement. Good control of focus, too. But where is the focal point? My eye kind of wanders around looking for something to settle on, but finds nothing.</td>', 'I like the choice of subject matter; many complex shapes, very organic, strong sense of movement. Good control of focus, too. But where is the focal point? My eye kind of wanders around looking for something to settle on, but finds nothing.', '2011-11-29 14:50:59.000000', NULL, 1),
(6605979, 985140, 114285, '<td valign="top">The orange tones grab, me this is great, and so so organic, even though the fruit is dead. 9</td>', 'The orange tones grab, me this is great, and so so organic, even though the fruit is dead. 9', '2011-11-29 20:02:04.000000', NULL, 1),
(6605984, 985561, 114225, '<td valign="top">What a cool plant. I''m not so keen on the vignetting that is darkening large parts of your subject.</td>', 'What a cool plant. I''m not so keen on the vignetting that is darkening large parts of your subject.', '2011-11-29 20:21:26.000000', NULL, 1),
