(6606835, 985670, 138545, '<td valign="top">Simply beautiful.</td>', 'Simply beautiful.', '2011-11-30 21:01:49.000000', NULL, 1),
(6606836, 985830, 138545, '<td valign="top">How gorgeous!</td>', 'How gorgeous!', '2011-11-30 21:03:54.000000', NULL, 1),
