(6610535, 985430, 124815, '<td valign="top">It would be too much to ask for a cactus to blossom year round. A truly botanical page.</td>', 'It would be too much to ask for a cactus to blossom year round. A truly botanical page.', '2011-12-04 19:50:33.000000', NULL, 1),
(6610536, 985257, 124815, '<td valign="top">If the challenge was "Velvet", this picture would be first page. Or be first page in this challenge!</td>', 'If the challenge was "Velvet", this picture would be first page. Or be first page in this challenge!', '2011-12-04 19:50:36.000000', NULL, 1),
(6610537, 985786, 124815, '<td valign="top">Wonderful</td>', 'Wonderful', '2011-12-04 19:50:41.000000', NULL, 1),
(6610539, 985752, 124815, '<td valign="top">I''ve never seen one in reality but as a child I have drawn it just like that! Like a Christmas ornament.</td>', 'I''ve never seen one in reality but as a child I have drawn it just like that! Like a Christmas ornament.', '2011-12-04 19:50:46.000000', NULL, 1),
(6610540, 984981, 124815, '<td valign="top">You made me go and search more for this marvel. Your image is very seductive</td>', 'You made me go and search more for this marvel. Your image is very seductive', '2011-12-04 19:50:59.000000', NULL, 1),
(6610541, 985032, 124815, '<td valign="top">Wow! I''ll pack my bags ... Hope you give its geographical coordinates</td>', 'Wow! I''ll pack my bags ... Hope you give its geographical coordinates', '2011-12-04 19:51:25.000000', NULL, 1),
(6610542, 985576, 124815, '<td valign="top">I see hope here for your beautiful leaf. Great color palette.</td>', 'I see hope here for your beautiful leaf. Great color palette.', '2011-12-04 19:52:25.000000', NULL, 1),
(6610543, 985757, 124815, '<td valign="top">talking about one letting one''s hair down!</td>', 'talking about one letting one''s hair down!', '2011-12-04 19:52:39.000000', NULL, 1),
(6610544, 985834, 124815, '<td valign="top">a case in which the enlarged aorta is a beautiful thing</td>', 'a case in which the enlarged aorta is a beautiful thing', '2011-12-04 19:52:59.000000', NULL, 1),
(6610545, 985718, 124815, '<td valign="top">So clean, cold and sanitized that it becomes an evil omen</td>', 'So clean, cold and sanitized that it becomes an evil omen', '2011-12-04 19:54:27.000000', NULL, 1),
(6610616, 984981, 50864, '<td valign="top">Beautiful. My favorite.</td>', 'Beautiful. My favorite.', '2011-12-04 21:22:04.000000', NULL, 1),
(6610627, 985642, 17507, '<td valign="top">Appealing abstraction--I like the high-contrast treatment. Sharp without being oversharp. Is this a negative image? -- The verticality makes this image feel a bit "stretched" to me: I find myself wishing the bottom 20 or 30% were cropped off.</td>', 'Appealing abstraction--I like the high-contrast treatment. Sharp without being oversharp. Is this a negative image? -- The verticality makes this image feel a bit "stretched" to me: I find myself wishing the bottom 20 or 30% were cropped off.', '2011-12-04 21:37:32.000000', NULL, 1),
(6610628, 985715, 17507, '<td valign="top">The rhythm and motion in this image is quite elegant. I like the color treatment, too. But I wish the edges were a bit sharper, and the black space at the top makes this photo feel a bit bottom-heavy.</td>', 'The rhythm and motion in this image is quite elegant. I like the color treatment, too. But I wish the edges were a bit sharper, and the black space at the top makes this photo feel a bit bottom-heavy.', '2011-12-04 21:38:35.000000', NULL, 1),
(6610629, 985353, 119419, '<td valign="top">Lovely little subject</td>', 'Lovely little subject', '2011-12-04 21:40:27.000000', NULL, 1),
(6610630, 985728, 17507, '<td valign="top">What a cool plant. Great choice of subject. Lighting seems like it''s a wee bit harsh, but not a big deal. Some selective sharpening on the fuzzy edges, and especially in the center of the plant, would had added a welcome bit of pop. Also, the yellow thing on the left and the roundish thing at the bottom, just left of center, are distracting--maybe crop out some of the left, clone out the thing at the bottom, or burn/desaturate it into obscurity?</td>', 'What a cool plant. Great choice of subject. Lighting seems like it''s a wee bit harsh, but not a big deal. Some selective sharpening on the fuzzy edges, and especially in the center of the plant, would had added a welcome bit of pop. Also, the yellow thing on the left and the roundish thing at the bottom, just left of center, are distracting--maybe crop out some of the left, clone out the thing at the bottom, or burn/desaturate it into obscurity?', '2011-12-04 21:41:25.000000', NULL, 1),
(6610631, 985830, 119419, '<td valign="top">Lovely little number, so creamy</td>', 'Lovely little number, so creamy', '2011-12-04 21:41:36.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6610632, 985635, 119419, '<td valign="top">Tough call on these reds, I turn the exposure right down in camera then boost in pp</td>', 'Tough call on these reds, I turn the exposure right down in camera then boost in pp', '2011-12-04 21:43:03.000000', NULL, 1),
(6610634, 985765, 17507, '<td valign="top">Beautiful flower, definitely appropriate for the challenge. I like the colors you''ve presented. But the processing makes the photo feel somehow flat, and the noise/grain in the background (namely at the top and bottom) distract from the smooth softness of the flower.</td>', 'Beautiful flower, definitely appropriate for the challenge. I like the colors you''ve presented. But the processing makes the photo feel somehow flat, and the noise/grain in the background (namely at the top and bottom) distract from the smooth softness of the flower.', '2011-12-04 21:43:31.000000', NULL, 1),
(6610635, 985737, 119419, '<td valign="top">Nice and sweet, bit lonely though</td>', 'Nice and sweet, bit lonely though', '2011-12-04 21:43:46.000000', NULL, 1),
(6610637, 985803, 17507, '<td valign="top">Meets the challenge, definitely--and nice colors--but where''s the focal point? Nothing is particularly sharp and the lighting is flat. Where is my eye supposed to rest? Without a focal point, my eye just sort of wanders out of the frame, which is not the effect a photo should have. The subject matter is quite promising, but the treatment leaves me feeling unsatisfied.</td>', 'Meets the challenge, definitely--and nice colors--but where''s the focal point? Nothing is particularly sharp and the lighting is flat. Where is my eye supposed to rest? Without a focal point, my eye just sort of wanders out of the frame, which is not the effect a photo should have. The subject matter is quite promising, but the treatment leaves me feeling unsatisfied.', '2011-12-04 21:45:43.000000', NULL, 1),
(6610639, 985806, 17507, '<td valign="top">Very cool concept, crisply delivered. I like it much, but wish you hadn''t lost the edges of the bulb; and it looks like some of the wire got blown out, too. Bit too much light, maybe, or simply too harsh. Still worth a 7 from me</td>', 'Very cool concept, crisply delivered. I like it much, but wish you hadn''t lost the edges of the bulb; and it looks like some of the wire got blown out, too. Bit too much light, maybe, or simply too harsh. Still worth a 7 from me', '2011-12-04 21:47:17.000000', NULL, 1),
(6610641, 985816, 119419, '<td valign="top">Lovely, I want one!</td>', 'Lovely, I want one!', '2011-12-04 21:50:13.000000', NULL, 1),
(6610642, 985453, 17507, '<td valign="top">Sunflower, right? -- I like the energy of all the curls and curves, but the white background and the cropping seem arbitrary to me. For me, black would have been a better background. There''s something about the slightly-off-center focal point combined with the excessive white space on the right that makes me feel kind of uneasy when I look at this photo.</td>', 'Sunflower, right? -- I like the energy of all the curls and curves, but the white background and the cropping seem arbitrary to me. For me, black would have been a better background. There''s something about the slightly-off-center focal point combined with the excessive white space on the right that makes me feel kind of uneasy when I look at this photo.', '2011-12-04 21:50:36.000000', NULL, 1),
(6610643, 985735, 119419, '<td valign="top">Rangakoo paws are nice, you got the red pretty hot Aussie!</td>', 'Rangakoo paws are nice, you got the red pretty hot Aussie!', '2011-12-04 21:51:22.000000', NULL, 1),
(6610644, 985761, 119419, '<td valign="top">Sweet as and wistful</td>', 'Sweet as and wistful', '2011-12-04 21:51:42.000000', NULL, 1),
(6610645, 985805, 17507, '<td valign="top">Elegance in minimalism and simplicity. Well done. A bit of sharpening on the edges of the "lanterns" and a softening of the highlight on the bottom right of the vase would have boosted the impact a lot for me.</td>', 'Elegance in minimalism and simplicity. Well done. A bit of sharpening on the edges of the "lanterns" and a softening of the highlight on the bottom right of the vase would have boosted the impact a lot for me.', '2011-12-04 21:52:23.000000', NULL, 1),
(6610646, 985650, 119419, '<td valign="top">Looks familiar but still spooky</td>', 'Looks familiar but still spooky', '2011-12-04 21:52:33.000000', NULL, 1),
(6610647, 985739, 119419, '<td valign="top">Nice mushroomy tones</td>', 'Nice mushroomy tones', '2011-12-04 21:53:16.000000', NULL, 1),
(6610648, 985703, 17507, '<td valign="top">Great tones, awesome abstraction. What if you made it a square crop and got rid of 25% or so of the left? I think that''d make this killer.</td>', 'Great tones, awesome abstraction. What if you made it a square crop and got rid of 25% or so of the left? I think that''d make this killer.', '2011-12-04 21:53:55.000000', NULL, 1),
(6610649, 985651, 119419, '<td valign="top">too close to the other challenge unfortunately</td>', 'too close to the other challenge unfortunately', '2011-12-04 21:54:25.000000', NULL, 1),
(6610650, 985689, 119419, '<td valign="top">nicely abstract</td>', 'nicely abstract', '2011-12-04 21:55:02.000000', NULL, 1),
(6610651, 985754, 119419, '<td valign="top">cute</td>', 'cute', '2011-12-04 21:55:09.000000', NULL, 1),
(6610654, 985230, 119419, '<td valign="top">nice dof, I feel the cold</td>', 'nice dof, I feel the cold', '2011-12-04 21:56:56.000000', NULL, 1),
(6610655, 985686, 119419, '<td valign="top">lovely</td>', 'lovely', '2011-12-04 21:57:46.000000', NULL, 1),
(6610656, 985448, 17507, '<td valign="top">Cliche title, no clear focal point, flat lighting, excessive yellow cast... it looks like you put some definite effort into this photo, but the end result just kind of hurts my eyes. More than anything else, I wish there were some WHITE in this photo, and the bloom at the top takes up too much space but delivers little in terms of photographic interest.</td>', 'Cliche title, no clear focal point, flat lighting, excessive yellow cast... it looks like you put some definite effort into this photo, but the end result just kind of hurts my eyes. More than anything else, I wish there were some WHITE in this photo, and the bloom at the top takes up too much space but delivers little in terms of photographic interest.', '2011-12-04 21:58:02.000000', NULL, 1),
(6610658, 985738, 119419, '<td valign="top">sure is, nice find</td>', 'sure is, nice find', '2011-12-04 21:58:06.000000', NULL, 1),
(6610660, 985812, 119419, '<td valign="top">grows on yer</td>', 'grows on yer', '2011-12-04 21:58:53.000000', NULL, 1),
(6610661, 985809, 119419, '<td valign="top">good light</td>', 'good light', '2011-12-04 21:59:04.000000', NULL, 1),
(6610662, 985225, 119419, '<td valign="top">scattered memories, nice</td>', 'scattered memories, nice', '2011-12-04 21:59:32.000000', NULL, 1),
(6610664, 985578, 119419, '<td valign="top">interesting, fresh looking.</td>', 'interesting, fresh looking.', '2011-12-04 21:59:52.000000', NULL, 1),
(6610665, 985607, 17507, '<td valign="top">I like the contrast between the organic shapes and the geometric frame of the greenhouse(?). The yellow/green/blue/brown palette is quite pleasing as well. But everything seems just a bit fuzzy, and there''s nowhere for my eye to rest. Did you have an intended focal point? The lack of one really detracts from this image for me, although this is clearly a rich location for shooting.</td>', 'I like the contrast between the organic shapes and the geometric frame of the greenhouse(?). The yellow/green/blue/brown palette is quite pleasing as well. But everything seems just a bit fuzzy, and there''s nowhere for my eye to rest. Did you have an intended focal point? The lack of one really detracts from this image for me, although this is clearly a rich location for shooting.', '2011-12-04 21:59:59.000000', NULL, 1),
